import { Table } from 'antd';
import { ColumnsType } from 'antd/lib/table';
import React from 'react';
import { Sample } from '..';
import {
  actionColumn,
  Actions,
  amountColumn,
  descriptionColumn,
  experimentsColumn,
  idColumn,
  locationColumn,
  noteColumn,
  symbolColumn,
  typeColumn,
  unitColumn,
} from '../helpers/sampleColumns';

interface Props {
  dataSource: Sample[];
  actions: Actions;
  loading?: boolean;
}

export function SampleTable(props: Props) {
  const columns: ColumnsType<Sample> = [
    idColumn,
    symbolColumn,
    locationColumn,
    descriptionColumn,
    amountColumn,
    unitColumn,
    typeColumn,
    experimentsColumn,
    noteColumn,
    actionColumn(props.actions),
  ];

  return <Table<Sample> columns={columns} bordered dataSource={props.dataSource} loading={props.loading}></Table>;
}
